arguments.new_str:
using Microsoft.ML;
using Microsoft.ML.Data;

var builder = WebApplication.CreateBuilder(args);

// ML.NET setup with fixed seed for reproducibility
var mlContext = new MLContext(seed: 42);
var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "customers.csv");

var data = mlContext.Data.LoadFromTextFile<CustomerData>(dataPath, hasHeader: true, separatorChar: ',');
var split = mlContext.Data.TrainTestSplit(data, testFraction: 0.2);

var pipeline = mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(CustomerData.Region))
    .Append(mlContext.Transforms.Concatenate("Features",
        nameof(CustomerData.Age),
        nameof(CustomerData.Income),
        "RegionEncoded",
        nameof(CustomerData.PurchaseHistory)))
    .Append(mlContext.Transforms.NormalizeMinMax("Features"))
    .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(
        labelColumnName: nameof(CustomerData.Churned),
        featureColumnName: "Features"));

Console.WriteLine("Training churn prediction model...");
var model = pipeline.Fit(split.TrainSet);

var predictions = model.Transform(split.TestSet);
var metrics = mlContext.BinaryClassification.Evaluate(predictions, labelColumnName: nameof(CustomerData.Churned));
Console.WriteLine($"Accuracy: {metrics.Accuracy:F4}");
Console.WriteLine($"AUC:      {metrics.AreaUnderRocCurve:F4}");
Console.WriteLine($"F1 Score: {metrics.F1Score:F4}");

builder.Services.AddPredictionEnginePool<CustomerData, ChurnPrediction>()
    .FromUri(modelName: "ChurnModel", uri: "", loadInitialModel: false);

var app = builder.Build();

// Pre-load the trained model into the pool
var enginePool = app.Services.GetRequiredService<Microsoft.Extensions.ML.PredictionEnginePool<CustomerData, ChurnPrediction>>();
mlContext.Model.Save(model, split.TrainSet.Schema, "churn_model.zip");
var poolField = typeof(Microsoft.Extensions.ML.PredictionEnginePool<CustomerData, ChurnPrediction>);

// Simpler approach: save model and reload via pool
builder = WebApplication.CreateBuilder(args);
var modelPath = Path.Combine(AppContext.BaseDirectory, "churn_model.zip");
mlContext.Model.Save(model, split.TrainSet.Schema, modelPath);

builder.Services.AddPredictionEnginePool<CustomerData, ChurnPrediction>()
    .FromFile(modelName: "ChurnModel", filePath: modelPath, watchForChanges: true);

app = builder.Build();

app.MapGet("/", () => "Churn Predictor API — POST to /predict");

app.MapPost("/predict", (CustomerData input,
    Microsoft.Extensions.ML.PredictionEnginePool<CustomerData, ChurnPrediction> pool) =>
{
    var result = pool.Predict("ChurnModel", input);
    return Results.Ok(new
    {
        input.Age,
        input.Income,
        input.Region,
        input.PurchaseHistory,
        WillChurn = result.PredictedLabel,
        Probability = result.Probability
    });
});

app.Run();

public class CustomerData
{
    [LoadColumn(0)] public float Age { get; set; }
    [LoadColumn(1)] public float Income { get; set; }
    [LoadColumn(2)] public string Region { get; set; } = "";
    [LoadColumn(3)] public float PurchaseHistory { get; set; }
    [LoadColumn(4), ColumnName("Churned")] public bool Churned { get; set; }
}

public class ChurnPrediction
{
    [ColumnName("PredictedLabel")] public bool PredictedLabel { get; set; }
    public float Probability { get; set; }
    public float Score { get; set; }
}

